insert into public.help_notes
  (section_key, section_label, placement, content, is_visible)
values
  ('form_overview', 'פתיח — איפה מוצאים את פרטי המנשא', 'form', 'את רוב פרטי המנשא אפשר למצוא על התווית, באתר היצרן או ב־WrapTrack. אם פרט מסוים אינו ידוע ולא ניתן לברר אותו, אפשר לבחור „לא ידוע”.', true),
  ('manufacturer', 'יצרן', 'form', 'brand — החברה שארגה את הבד.', true),
  ('manufacturer_add', 'הוספת יצרן חדש', 'form', 'היצרן לא נמצא ברשימה? אפשר להוסיף אותו. יש לכתוב את השם המלא והמקובל באותיות לטיניות, אחרי שמוודאים שהוא אינו מופיע כבר באיות אחר. אל חשש — מנהלת תעבור בהמשך על יצרנים חדשים ותאחד או תתקן אותם במידת הצורך.', true),
  ('design', 'עיצוב', 'form', 'design — למשל לה ויטה (של יארו) או אוקינמי (של אושה). ניתן לציין בעברית או באנגלית.', true),
  ('model', 'מודל', 'form', 'model — מתייחס לצבעים או לחומרים של העיצוב.', true),
  ('size', 'מידה', 'form', E'צ׳יט שיט — אורכים משוערים:\nמידה 2 — 2.7–2.8 מ׳\nמידה 3 — 3.2 מ׳\nמידה 4 — 3.6–3.7 מ׳\nמידה 5 — 4.2 מ׳\nמידה 6 — 4.6–4.7 מ׳\nמידה 7 — 5.2 מ׳\nמידה 8 — 5.6–5.8 מ׳\nמידה 9 — 6.2 מ׳', true),
  ('size_note', 'הערת מידה', 'form', 'אפשר להוסיף מידע מדויק יותר, למשל: מנשא טבעות קצר, מידה 4 ארוכה, האורך המדוד של המנשא, אם הוא קוצר ממנשא אחר או המידות המדויקות של סקראפ.', true),
  ('gsm', 'GSM', 'form', 'GSM הוא משקל הבד בגרמים למטר רבוע. בדרך כלל אפשר למצוא אותו על התווית, באתר היצרן או ב־WrapTrack.', true),
  ('materials_unknown', 'הרכב חומרים לא ידוע', 'form', 'נא לסמן רק במצב שבאמת לא ניתן לברר.', true),
  ('material_add', 'הוספת חומר חדש', 'form', 'אם חסר חומר, אפשר להוסיף אותו ולעדכן כמיטב היכולת. בהמשך מנהלת תעבור על חומרים חדשים ותערוך אותם במידת הצורך.', true),
  ('material_name', 'שם חומר חדש', 'form', 'הפורמט הוא שם ואז תיאור; למשל „כותנה מצרית” ולא רק „מצרית”.', true),
  ('material_parent', 'קטגוריית חומר חדש', 'form', 'יש לבחור את המשפחה המתאימה. אם יש ספק, מומלץ לבחור „שונות”.', true),
  ('material_origin', 'סוג / מקור חומר חדש', 'form', 'טבעי — הסיב גדל בצורתו כסיב, למשל כותנה או צמר. מלאכותי — מקור טבעי שעובד לסיב. סינתטי — סיב שמיוצר מפולימרים, למשל פוליאסטר או ניילון. אחר — כשלא ברור לאיזה סוג החומר שייך.', true),
  ('colors', 'צבעים', 'form', 'מומלץ לסמן את כל הצבעים שמופיעים במנשא, בלי להתעכב על דיוק מושלם. השפה מוגבלת בתיאור צבעים, ומה שנראה לאדם אחד כתום עשוי להיראות לאחר ורוד; מידה מסוימת של שונות ואי־ודאות היא צפויה.', true),
  ('color_patterns', 'תכונות / מבנה צבע', 'form', 'אין חובה לסמן. זהו סיווג נוסף שיכול לעזור בחיפוש — בעיקר בשלב שבו עוד נעזרים בהבדלים בין צבעי הבד בזמן הקשירה, וגם לחובבי פסים, אומברה, קשת ודוגמאות דומות.', true),
  ('condition', 'מצב המנשא', 'form', E'יש לבחור את רמת השימוש הכוללת; פגמים מתוארים בנפרד.\n\nלא היה בשימוש — המנשא לא כובס, לא נוסה ולא נלבש. עדיין במצב שבו נמכר.\nהיה קצת בשימוש — המנשא כובס או נמדד, אבל לא נעשה בו שימוש.\nהיה בשימוש אך עדיין לא התרכך — המנשא היה בשימוש תקופה, אבל עדיין לא התרכך.\nמרוכך — המנשא עבר שימוש מספיק כדי להיות רך ונוח לקשירה.\nמעט בלוי — המנשא כבר שחוק, רך מדי או גמיש.\nבלוי — קיימים סימני שימוש ובלאי משמעותיים.', true),
  ('price', 'מחיר', 'form', 'איך אפשר לקבוע מחיר למנשא יד שנייה?', true),
  ('shipping', 'משלוח', 'form', 'נהוג שדמי המשלוח משולמים על ידי הקונה, אלא אם סוכם אחרת.', true),
  ('filter_logic', 'לוגיקת סינון — או / וגם', 'search', 'כשבוחרים כמה אפשרויות בתוך אותו סוג סינון, תופיע מודעה שמתאימה לפחות לאחת מהן. בין סוגי סינון שונים נדרשת התאמה לכולם.', true),
  ('size', 'מידה', 'search', E'אורכים משוערים:\nמידה 2 — 2.7–2.8 מ׳\nמידה 3 — 3.2 מ׳\nמידה 4 — 3.6–3.7 מ׳\nמידה 5 — 4.2 מ׳\nמידה 6 — 4.6–4.7 מ׳\nמידה 7 — 5.2 מ׳\nמידה 8 — 5.6–5.8 מ׳\nמידה 9 — 6.2 מ׳', true),
  ('gsm', 'GSM', 'search', 'אפשר לבחור ערך GSM מינימלי ומקסימלי. כאשר מוגדר טווח, מודעות שבהן ה־GSM אינו ידוע יוצגו רק אם תיבחר האפשרות „לכלול גם GSM לא ידוע”.', true),
  ('size', 'מידה', 'listing', 'טבלת מידות ועזרה בבחירת מידה.', true),
  ('price', 'מחיר', 'listing', 'מידע על תמחור מנשא יד שנייה.', true),
  ('gsm', 'GSM', 'listing', 'GSM הוא משקל הבד בגרמים למטר רבוע.', true),
  ('materials', 'חומרים', 'listing', 'טבעוני פירושו ללא משי, צמר או סיבים מן החי; טבעי פירושו שכל הסיבים טבעיים; איזיקייר ניתן למשפחות הכותנה והסינתטיים.', true),
  ('shipping', 'משלוח', 'listing', 'נהוג שדמי המשלוח משולמים על ידי הקונה, אלא אם סוכם אחרת.', true),
  ('condition', 'מצב המנשא', 'listing', E'לא היה בשימוש — המנשא לא כובס, לא נוסה ולא נלבש. עדיין במצב שבו נמכר.\nהיה קצת בשימוש — המנשא כובס או נמדד, אבל לא נעשה בו שימוש.\nהיה בשימוש אך עדיין לא התרכך — המנשא היה בשימוש תקופה, אבל עדיין לא התרכך.\nמרוכך — המנשא עבר שימוש מספיק כדי להיות רך ונוח לקשירה.\nמעט בלוי — המנשא כבר שחוק, רך מדי או גמיש.\nבלוי — קיימים סימני שימוש ובלאי משמעותיים.', true)
